const crypto = require('crypto');
const secret = $env.WEBHOOK_HMAC_SECRET;
if (!secret) throw new Error('WEBHOOK_HMAC_SECRET is not set');

const item = $input.first();
const headers = item.json.headers ?? {};
const signature = headers['x-lendloop-signature'] ?? headers['X-LendLoop-Signature'];
const rawBody = typeof item.json.body === 'string'
  ? item.json.body
  : JSON.stringify(item.json.body ?? item.json);

const expected = crypto.createHmac('sha256', secret).update(rawBody).digest('hex');
if (!signature || signature.toLowerCase() !== expected.toLowerCase()) {
  throw new Error('Invalid X-LendLoop-Signature');
}

const payload = JSON.parse(rawBody);
return [{ json: payload }];

const p = $input.first().json;
const who = p.notify;
try {
  if ($env.SIMULATE_DELIVERY_FAIL === '1') {
    throw new Error('Simulated delivery failure (SIMULATE_DELIVERY_FAIL)');
  }
  const email = (who?.email ?? '').trim();
  if (!email) {
    throw new Error('Missing recipient email');
  }
  const line = `${p.event} — ${p.toolName} (${p.startDate} → ${p.endDate}), status ${p.status}. Notify ${who.role}: ${who.name} <${email}>`;
  console.log(line);
  return [{ json: p }];
} catch (error) {
  const detail = error instanceof Error ? error.message : String(error);
  console.error('Request notification failed:', detail);
  throw error;
}
